import hashlib
from collections import defaultdict
from pathlib import Path

FOLDER = Path(r"C:\Users\[you]\Pictures")


def file_hash(path, chunk_size=1024 * 1024):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        while chunk := f.read(chunk_size):
            digest.update(chunk)
    return digest.hexdigest()


by_size = defaultdict(list)
for path in FOLDER.rglob("*"):
    if path.is_file():
        by_size[path.stat().st_size].append(path)

groups = 0
for paths in by_size.values():
    if len(paths) < 2:
        continue
    by_hash = defaultdict(list)
    for path in paths:
        by_hash[file_hash(path)].append(path)
    for same in by_hash.values():
        if len(same) > 1:
            groups += 1
            print(f"Duplicate set {groups}:")
            for path in same:
                print(f"  {path}")

print(f"{groups} sets of duplicates found.")
```

It only compares files of the same size, so it doesn't read every photo twice. Nothing is moved or deleted.
